insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('be1b1294-a7ae-49a8-827a-514e2266be25', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', null, 'topic'::public.curated_course_node_type, 'Food and Beverage Industry Systems and Service Models', 'This section gives students a systems view of food and beverage operations. They learn how concept, market, menu, production, service, people, technology, facilities, controls, and external conditions work together to create guest and business outcomes.', 0),
  ('312b35f9-c481-46a0-a452-6a9da218e91e', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'be1b1294-a7ae-49a8-827a-514e2266be25', 'subtopic'::public.curated_course_node_type, 'Industry structure and operating contexts', 'Students compare the missions, economics, and operating patterns of major food and beverage sectors.', 0),
  ('3f926331-6cfa-4c0b-b370-2891a103f883', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '312b35f9-c481-46a0-a452-6a9da218e91e', 'concept'::public.curated_course_node_type, 'Independent restaurants, chains, franchises, hotels, resorts, clubs, cruise, gaming, attractions, institutions, and contract foodservice', null, 0),
  ('845c93b9-efd6-4b7f-bdcf-23622e0b2dac', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '312b35f9-c481-46a0-a452-6a9da218e91e', 'concept'::public.curated_course_node_type, 'Quick service, fast casual, casual, polished casual, fine dining, cafés, bars, ghost kitchens, food halls, and pop-ups', null, 1),
  ('9bcc4893-84c8-4e47-b990-24f7727a6608', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '312b35f9-c481-46a0-a452-6a9da218e91e', 'concept'::public.curated_course_node_type, 'On-premise, off-premise, delivery, takeout, drive-through, catering, and hybrid channels', null, 2),
  ('b01f4626-d57f-4968-b7b8-080968b90af9', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'be1b1294-a7ae-49a8-827a-514e2266be25', 'subtopic'::public.curated_course_node_type, 'Foodservice systems model', 'The systems lens helps managers diagnose causes and anticipate the downstream effect of a decision.', 1),
  ('0c6fd857-4a2c-4a01-ae4d-9e080f31f40a', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'b01f4626-d57f-4968-b7b8-080968b90af9', 'concept'::public.curated_course_node_type, 'Inputs: people, products, money, facilities, information, brand, and time', null, 0),
  ('9cbc48c3-a723-443b-a722-e544d626f998', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'b01f4626-d57f-4968-b7b8-080968b90af9', 'concept'::public.curated_course_node_type, 'Transformation: purchasing, production, service, selling, control, and management processes', null, 1),
  ('88f9b183-4c73-4c8e-b9e2-93146500d73b', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'b01f4626-d57f-4968-b7b8-080968b90af9', 'concept'::public.curated_course_node_type, 'Outputs: guest value, safety, quality, employee outcomes, revenue, profit, reputation, and waste', null, 2),
  ('37bd7f31-548c-4036-acf8-01bbb8f76c5d', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'b01f4626-d57f-4968-b7b8-080968b90af9', 'concept'::public.curated_course_node_type, 'Boundaries, interfaces, feedback, control, and environmental forces', null, 3),
  ('5e4bcfe0-b9c6-4d3d-a6f5-3b34f20db93b', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'be1b1294-a7ae-49a8-827a-514e2266be25', 'subtopic'::public.curated_course_node_type, 'Management roles and operating rhythm', 'Students learn how managers translate plans into coordinated daily execution.', 2),
  ('fba9b003-18dd-435d-9a76-8513144078b8', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '5e4bcfe0-b9c6-4d3d-a6f5-3b34f20db93b', 'concept'::public.curated_course_node_type, 'Planning, organizing, staffing, leading, controlling, and continuous improvement', null, 0),
  ('7ebacced-4358-45de-9be7-24cbb2bf0302', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '5e4bcfe0-b9c6-4d3d-a6f5-3b34f20db93b', 'concept'::public.curated_course_node_type, 'Opening, shift, changeover, closing, weekly, period-end, and seasonal management cycles', null, 1),
  ('e7d03c46-89b7-491d-8745-146a74995e99', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '5e4bcfe0-b9c6-4d3d-a6f5-3b34f20db93b', 'concept'::public.curated_course_node_type, 'Manager-on-duty responsibilities, line checks, pre-shifts, handoffs, logs, escalation, and post-shift review', null, 2),
  ('9bed00f5-06ec-4fa9-b14e-b9b597b04b77', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', null, 'topic'::public.curated_course_node_type, 'Concept Development, Market Fit, and Feasibility', 'A compelling idea is not yet a viable operation. This section teaches students to define a target market, value proposition, service promise, operating model, and financial logic before committing resources.', 1),
  ('55a82be6-5dde-4ac9-a5b5-24ae4cb73226', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '9bed00f5-06ec-4fa9-b14e-b9b597b04b77', 'subtopic'::public.curated_course_node_type, 'Market and guest analysis', 'Students gather evidence about demand, occasions, competitors, and unmet needs.', 0),
  ('451019cd-779e-4118-a96d-f2e9b545e11a', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '55a82be6-5dde-4ac9-a5b5-24ae4cb73226', 'concept'::public.curated_course_node_type, 'Primary and secondary research, observation, intercepts, surveys, interviews, and demand data', null, 0),
  ('0f41f374-4e6e-422c-9299-b96f8146450a', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '55a82be6-5dde-4ac9-a5b5-24ae4cb73226', 'concept'::public.curated_course_node_type, 'Segmentation by need, occasion, behavior, spending, and channel without stereotyping', null, 1),
  ('f9fbd7c7-f54b-446d-9589-ba945423bb62', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '55a82be6-5dde-4ac9-a5b5-24ae4cb73226', 'concept'::public.curated_course_node_type, 'Competitive set, trade area, location, daypart, seasonality, trends, and substitution', null, 2),
  ('54a784f5-d97d-4dfe-9ada-e92a6c737a18', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '9bed00f5-06ec-4fa9-b14e-b9b597b04b77', 'subtopic'::public.curated_course_node_type, 'Concept statement and experience design', 'Students create a coherent concept in which every visible and backstage choice reinforces the promise.', 1),
  ('2733160b-d7c1-41fe-a8c2-897401b0193e', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '54a784f5-d97d-4dfe-9ada-e92a6c737a18', 'concept'::public.curated_course_node_type, 'Target guest, need state, value proposition, cuisine, beverage identity, price position, atmosphere, and service model', null, 0),
  ('07adb05e-f32f-4d95-933a-a09514cf39a6', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '54a784f5-d97d-4dfe-9ada-e92a6c737a18', 'concept'::public.curated_course_node_type, 'Brand story, name, design cues, music, lighting, uniforms, tableware, packaging, and sensory experience', null, 1),
  ('6c2e319e-69f8-4b2b-a1fa-79ca806f86a2', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '54a784f5-d97d-4dfe-9ada-e92a6c737a18', 'concept'::public.curated_course_node_type, 'Guest journey, service blueprint, moments of truth, accessibility, and recovery points', null, 2),
  ('67ed9870-db9c-4cc5-915e-ee793dcc20f9', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '9bed00f5-06ec-4fa9-b14e-b9b597b04b77', 'subtopic'::public.curated_course_node_type, 'Feasibility and business model', 'Students test whether the concept can attract enough demand and operate within capital, labor, facility, supply, and legal constraints.', 2),
  ('22d664bd-8248-47e0-ab6e-33ca89c1666a', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '67ed9870-db9c-4cc5-915e-ee793dcc20f9', 'concept'::public.curated_course_node_type, 'Revenue streams, channels, check average, turns, seats, capacity, and demand assumptions', null, 0),
  ('2a43ba8c-04f2-4aa8-a638-12403cf638d3', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '67ed9870-db9c-4cc5-915e-ee793dcc20f9', 'concept'::public.curated_course_node_type, 'Site criteria, licenses, equipment, staffing, suppliers, technology, opening timeline, and working capital', null, 1),
  ('9f6c8dc7-4f1a-4091-be46-41f86123bcd5', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '67ed9870-db9c-4cc5-915e-ee793dcc20f9', 'concept'::public.curated_course_node_type, 'Break-even, sensitivity, scenario analysis, risk register, go/no-go criteria, and ethical implications', null, 2),
  ('649b39b6-8b49-4cff-9d1f-1ca7950da38f', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', null, 'topic'::public.curated_course_node_type, 'Menu Planning, Engineering, Pricing, and Product Development', 'The menu is the operation’s primary merchandising, production, procurement, labor, and profitability tool. Students design menus that are desirable, executable, inclusive, safe, and financially sound.', 2),
  ('0f441000-e2b8-4f17-8488-3ecb29050e58', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '649b39b6-8b49-4cff-9d1f-1ca7950da38f', 'subtopic'::public.curated_course_node_type, 'Menu architecture and product mix', 'Students organize an offer around guest needs, concept identity, operational capacity, and balanced choice.', 0),
  ('435acf69-1707-4e7c-9e02-320a3e9f1e4a', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '0f441000-e2b8-4f17-8488-3ecb29050e58', 'concept'::public.curated_course_node_type, 'Static, cycle, seasonal, tasting, table d’hôte, prix fixe, à la carte, limited, and digital menus', null, 0),
  ('25fdb3c4-0147-493a-ba8c-fc7d6dc2fc07', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '0f441000-e2b8-4f17-8488-3ecb29050e58', 'concept'::public.curated_course_node_type, 'Category structure, item count, cross-utilization, dayparts, dietary patterns, allergens, and children’s offers', null, 1),
  ('ae34ddc2-dcc6-4193-8e33-a320cba38794', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '0f441000-e2b8-4f17-8488-3ecb29050e58', 'concept'::public.curated_course_node_type, 'Variety, balance, signature items, local/global influences, seasonality, and trend evaluation', null, 2),
  ('a866c91f-b674-47c8-80d2-237bcbe71490', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '649b39b6-8b49-4cff-9d1f-1ca7950da38f', 'subtopic'::public.curated_course_node_type, 'Recipe and product development', 'Students turn an idea into a repeatable product with defined quality, cost, yield, safety, and service requirements.', 1),
  ('9297b56d-53fc-4ecb-b355-30f22af1f6d0', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'a866c91f-b674-47c8-80d2-237bcbe71490', 'concept'::public.curated_course_node_type, 'Standardized recipes, specifications, weights/measures, methods, equipment, batch size, portions, plating, holding, and shelf life', null, 0),
  ('e3581dc9-f165-4ffd-b0dc-20506230296b', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'a866c91f-b674-47c8-80d2-237bcbe71490', 'concept'::public.curated_course_node_type, 'Recipe scaling, conversion factors, yield tests, cooking loss, edible portion, nutrient/allergen review, and version control', null, 1),
  ('577a8b59-d7fe-4b2b-9d6a-8f5d56ea9ac0', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'a866c91f-b674-47c8-80d2-237bcbe71490', 'concept'::public.curated_course_node_type, 'Pilot tests, sensory evaluation, speed of service, packaging/delivery trials, and launch approval', null, 2),
  ('dfb747c6-c57c-4e09-bccb-c4bc631a7ee0', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '649b39b6-8b49-4cff-9d1f-1ca7950da38f', 'subtopic'::public.curated_course_node_type, 'Menu engineering and pricing', 'Students combine popularity, contribution, guest value, competitive context, and behavioral design rather than using food-cost percentage alone.', 2),
  ('67739755-2156-4032-8c30-7697ee11cd0d', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'dfb747c6-c57c-4e09-bccb-c4bc631a7ee0', 'concept'::public.curated_course_node_type, 'Item food/beverage cost, selling price, contribution margin, popularity, menu mix, and category benchmarks', null, 0),
  ('236e7d2d-a630-4bf2-ba76-cd2c4e35a9ef', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'dfb747c6-c57c-4e09-bccb-c4bc631a7ee0', 'concept'::public.curated_course_node_type, 'Stars, plowhorses, puzzles, dogs; limitations of the classic matrix and use of demand/operational data', null, 1),
  ('15765b47-ab61-4588-b49e-9315a88f62f9', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'dfb747c6-c57c-4e09-bccb-c4bc631a7ee0', 'concept'::public.curated_course_node_type, 'Cost-plus, contribution, value-based, competitive, bundle, dynamic, and psychological pricing', null, 2);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('2755721a-1fdf-4ebf-826e-a8a1ce0508cc', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'dfb747c6-c57c-4e09-bccb-c4bc631a7ee0', 'concept'::public.curated_course_node_type, 'Menu layout, descriptions, placement, anchors, modifiers, add-ons, ethics, and test design', null, 3),
  ('2b0d500f-1e0b-4237-a232-1233e3251f68', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', null, 'topic'::public.curated_course_node_type, 'Purchasing, Receiving, Storage, and Inventory', 'Profitable operations depend on obtaining the specified product at the right total cost and protecting it through receiving and storage. Students learn controls that support quality, safety, traceability, cash, and continuity.', 3),
  ('989e1b5d-7379-4f4d-947b-fee1cc73c814', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '2b0d500f-1e0b-4237-a232-1233e3251f68', 'subtopic'::public.curated_course_node_type, 'Purchasing strategy and specifications', 'Students define what must be purchased and select a sourcing method appropriate to volume, risk, quality, and market conditions.', 0),
  ('3d7ede7c-a477-4263-ae2b-64be3ed67e1c', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '989e1b5d-7379-4f4d-947b-fee1cc73c814', 'concept'::public.curated_course_node_type, 'Make-or-buy, centralized/decentralized purchasing, group purchasing, prime vendor, local sourcing, and spot buys', null, 0),
  ('52c07cef-7d2d-4f02-8aa3-8db33e922892', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '989e1b5d-7379-4f4d-947b-fee1cc73c814', 'concept'::public.curated_course_node_type, 'Product identity, grade, size, pack, brand/equivalent, yield, quality, safety, allergen, sustainability, delivery, and rejection criteria', null, 1),
  ('ba06687f-c791-4072-b87c-a0bc83f2756a', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '989e1b5d-7379-4f4d-947b-fee1cc73c814', 'concept'::public.curated_course_node_type, 'Quotes, bids, proposals, contracts, negotiation, ethics, conflicts of interest, and total cost of ownership', null, 2),
  ('d1491a05-86f7-4ddb-94ad-9dfb19a1ca03', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '2b0d500f-1e0b-4237-a232-1233e3251f68', 'subtopic'::public.curated_course_node_type, 'Supplier and supply-chain management', 'Students evaluate suppliers as performance and risk partners rather than price lists.', 1),
  ('51ebbccf-cfa4-424f-9585-4a049f5f58e0', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'd1491a05-86f7-4ddb-94ad-9dfb19a1ca03', 'concept'::public.curated_course_node_type, 'Qualification, insurance, licenses, food-safety evidence, audits, service area, credit, and capacity', null, 0),
  ('84153cee-5b3b-4eca-adb1-30ae8e59bf25', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'd1491a05-86f7-4ddb-94ad-9dfb19a1ca03', 'concept'::public.curated_course_node_type, 'Scorecards for fill rate, quality, accuracy, timeliness, substitutions, claims, responsiveness, and price', null, 1),
  ('b9b9f498-a384-451b-84b9-bde81436eeca', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'd1491a05-86f7-4ddb-94ad-9dfb19a1ca03', 'concept'::public.curated_course_node_type, 'Forecast sharing, alternate suppliers, shortages, recalls, fraud, provenance, and disruption planning', null, 2),
  ('be2a72a5-7208-4006-9ea4-b0f75f94cafa', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '2b0d500f-1e0b-4237-a232-1233e3251f68', 'subtopic'::public.curated_course_node_type, 'Receiving, storage, and inventory control', 'Students control the point where ownership, safety, and financial responsibility transfer.', 2),
  ('7880d5bd-86c9-4a62-9ae7-5b11d61fd7ba', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'be2a72a5-7208-4006-9ea4-b0f75f94cafa', 'concept'::public.curated_course_node_type, 'Delivery scheduling, invoice/purchase-order match, count/weight, temperature, condition, date/lot code, acceptance, rejection, and credits', null, 0),
  ('0ccb068c-da1a-4c31-bc5f-e890339ee5b0', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'be2a72a5-7208-4006-9ea4-b0f75f94cafa', 'concept'::public.curated_course_node_type, 'Dry, chilled, frozen, beverage, chemical, allergen, high-value, and secure storage', null, 1),
  ('be1e8c41-ae66-4c91-81ac-9b85f95d6538', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'be2a72a5-7208-4006-9ea4-b0f75f94cafa', 'concept'::public.curated_course_node_type, 'FIFO/FEFO, par stock, perpetual and physical inventory, turnover, valuation, variance, shrinkage, breakage, and cycle counts', null, 2),
  ('57f1f2fd-ac71-4cfe-b3d1-67340ea073e8', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', null, 'topic'::public.curated_course_node_type, 'Kitchen Production, Food Safety, and Quality Assurance', 'Kitchen systems convert menu demand into consistent products under time, safety, labor, space, and equipment constraints. Students learn to plan production and build quality and food safety into the process.', 4),
  ('d8ad9b1a-d422-4cf8-bf88-0edb55adee65', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '57f1f2fd-ac71-4cfe-b3d1-67340ea073e8', 'subtopic'::public.curated_course_node_type, 'Production systems and workflow', 'Students match the production method, batch size, and timing to demand and quality targets.', 0),
  ('334e5d38-4ac2-4f4d-9541-8620083e5c5b', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'd8ad9b1a-d422-4cf8-bf88-0edb55adee65', 'concept'::public.curated_course_node_type, 'Cook-serve, batch cooking, cook-chill, sous-vide where approved, commissary, assembly-serve, and central kitchens', null, 0),
  ('fa9f8378-b8b3-492d-84f8-2c1f4e78ece8', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'd8ad9b1a-d422-4cf8-bf88-0edb55adee65', 'concept'::public.curated_course_node_type, 'Forecasts, prep lists, production sheets, mise en place, sequencing, critical paths, bottlenecks, and station balance', null, 1),
  ('9ae14e81-a176-4dba-9b73-b61e942b1b39', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'd8ad9b1a-d422-4cf8-bf88-0edb55adee65', 'concept'::public.curated_course_node_type, 'Service pacing, firing, expediting, hot/cold holding, replenishment, overproduction, and close-down decisions', null, 2),
  ('df565fe2-dc11-425b-b4c0-144ecf10bf35', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '57f1f2fd-ac71-4cfe-b3d1-67340ea073e8', 'subtopic'::public.curated_course_node_type, 'Active managerial control and sanitation', 'Students use preventive controls and verification rather than depending on inspection alone.', 1),
  ('793731ac-517a-482a-86eb-ed4f1c9b987b', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'df565fe2-dc11-425b-b4c0-144ecf10bf35', 'concept'::public.curated_course_node_type, 'Biological, chemical, physical, and allergen hazards; prerequisite programs and process approach', null, 0),
  ('fb0b0f8d-ab45-41e0-a53c-9bb320171e78', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'df565fe2-dc11-425b-b4c0-144ecf10bf35', 'concept'::public.curated_course_node_type, 'Employee health, hand hygiene, approved source, cross-contamination, time-temperature control, cooling, reheating, and date marking', null, 1),
  ('8d3451d5-f36e-4f5d-aca9-a8eae06124ae', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'df565fe2-dc11-425b-b4c0-144ecf10bf35', 'concept'::public.curated_course_node_type, 'Cleaning versus sanitizing, warewashing, master schedules, pest management, chemical control, monitoring, corrective action, verification, and records', null, 2),
  ('b0ac7746-be5e-42c4-8671-cbe8009df350', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '57f1f2fd-ac71-4cfe-b3d1-67340ea073e8', 'subtopic'::public.curated_course_node_type, 'Quality assurance and waste control', 'Students define acceptable product and process performance, find variation, and correct root causes.', 2),
  ('68dfcd15-6815-4049-9ddd-9ea2caa2f733', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'b0ac7746-be5e-42c4-8671-cbe8009df350', 'concept'::public.curated_course_node_type, 'Sensory and technical standards, line checks, portion tools, calibration, holding limits, plate presentation, and defect criteria', null, 0),
  ('0b64917d-82f4-4bed-bf0d-48633a155930', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'b0ac7746-be5e-42c4-8671-cbe8009df350', 'concept'::public.curated_course_node_type, 'Yield variance, rework, spoilage, trim, overproduction, returns, comps, and pre/post-consumer waste', null, 1),
  ('5e9c6124-fe38-46f3-b8a2-c6556f623fb2', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'b0ac7746-be5e-42c4-8671-cbe8009df350', 'concept'::public.curated_course_node_type, 'Specification review, process audit, Pareto analysis, root cause, PDSA testing, standard work, and sustainment', null, 2),
  ('7456b360-0e62-4068-9fc7-e73b3de330ef', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', null, 'topic'::public.curated_course_node_type, 'Beverage Operations and Responsible Service', 'Beverage programs can drive identity and margin but also create legal, safety, inventory, and social responsibility risks. Students learn product knowledge, program design, controls, and responsible service across alcoholic and nonalcoholic categories.', 5),
  ('cb1506bc-4a3e-4bd1-bba6-bd83233571cb', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '7456b360-0e62-4068-9fc7-e73b3de330ef', 'subtopic'::public.curated_course_node_type, 'Beverage categories and program design', 'Students build a coherent beverage mix for the concept, guest, food menu, occasion, and operational capability.', 0),
  ('228655c7-da1b-4fd6-a830-a1fad24729e0', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'cb1506bc-4a3e-4bd1-bba6-bd83233571cb', 'concept'::public.curated_course_node_type, 'Water, coffee, tea, juice, soft drinks, functional drinks, no/low-alcohol options, beer, wine, cider, spirits, cocktails, and mocktails', null, 0),
  ('4d6b9a70-67f2-4d38-a3ef-55bef6949d71', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'cb1506bc-4a3e-4bd1-bba6-bd83233571cb', 'concept'::public.curated_course_node_type, 'Sensory vocabulary, production basics, style, origin, seasonality, trends, food pairing, and inclusive choice', null, 1),
  ('f933e869-4c88-4728-89e6-db67aa8e822a', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'cb1506bc-4a3e-4bd1-bba6-bd83233571cb', 'concept'::public.curated_course_node_type, 'List structure, by-the-glass versus bottle, draft systems, batching, garnish, glassware, equipment, and speed', null, 2),
  ('821a5534-fe1c-416c-a6ab-7b7ce9d9dce9', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '7456b360-0e62-4068-9fc7-e73b3de330ef', 'subtopic'::public.curated_course_node_type, 'Costing, pricing, purchasing, and controls', 'Students use recipe, portion, inventory, and sales controls to protect quality and contribution.', 1),
  ('1b145c92-7543-4363-8f8c-d892eb56e83b', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '821a5534-fe1c-416c-a6ab-7b7ce9d9dce9', 'concept'::public.curated_course_node_type, 'Standard pour, beverage recipes, yield, cost per serving, beverage-cost percentage, contribution, and price architecture', null, 0),
  ('92397ee3-e00d-426f-b29d-22ef641a7817', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '821a5534-fe1c-416c-a6ab-7b7ce9d9dce9', 'concept'::public.curated_course_node_type, 'Supplier relations, legal purchasing channels, receiving records, cellar/bar storage, requisitions, transfers, and perpetual inventory', null, 1),
  ('5415c385-365a-427c-be5b-e8575fe4cb1a', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '821a5534-fe1c-416c-a6ab-7b7ce9d9dce9', 'concept'::public.curated_course_node_type, 'Bottle weights/counts, draft yield, spill, breakage, comps, voids, theft, overpouring, variance, and closing controls', null, 2),
  ('69a8c141-24ef-4c70-b49d-50e79f31c5db', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '7456b360-0e62-4068-9fc7-e73b3de330ef', 'subtopic'::public.curated_course_node_type, 'Alcohol law and responsible service', 'Students understand that responsible service is a core duty of care and that applicable law varies by jurisdiction.', 2),
  ('7f10e56c-2480-4abe-b72c-9a1c80322d03', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '69a8c141-24ef-4c70-b49d-50e79f31c5db', 'concept'::public.curated_course_node_type, 'Licensing, age verification, hours, service limits, promotions, advertising, records, tax, and local authority', null, 0),
  ('5807c322-300c-4606-bb33-e7947dd0bb32', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '69a8c141-24ef-4c70-b49d-50e79f31c5db', 'concept'::public.curated_course_node_type, 'Intoxication cues, standard-drink concepts, pacing, food/water, refusal, intervention, incident documentation, transport, and security', null, 1),
  ('dad33017-abb1-42f0-9d5a-61aaf3fafe42', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '69a8c141-24ef-4c70-b49d-50e79f31c5db', 'concept'::public.curated_course_node_type, 'Server training, manager escalation, third-party delivery, dram-shop/social-host exposure, insurance, and alcohol-free hospitality', null, 2);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('3f724acd-db34-4e7f-8b09-bc2b0b518002', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', null, 'topic'::public.curated_course_node_type, 'Service Operations, Guest Experience, and Recovery', 'Service is a designed operating system, not simply employee friendliness. Students learn to coordinate demand, capacity, standards, communication, and human judgment to create consistent and inclusive experiences.', 6),
  ('60270749-f737-456c-84f1-0f7e0fc63cb5', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '3f724acd-db34-4e7f-8b09-bc2b0b518002', 'subtopic'::public.curated_course_node_type, 'Service styles and sequence', 'Students compare service models and establish standards suited to the concept and guest.', 0),
  ('efaf5a38-202e-4483-88b8-1d98b98c49e3', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '60270749-f737-456c-84f1-0f7e0fc63cb5', 'concept'::public.curated_course_node_type, 'Counter, quick, casual, table, synchronized, buffet, family, banquet, room, bar, and delivery service', null, 0),
  ('ed9957c5-ad05-45ad-bbb3-e8daab1f9593', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '60270749-f737-456c-84f1-0f7e0fc63cb5', 'concept'::public.curated_course_node_type, 'Greeting, seating/queue, order, coursing, beverage, check-back, clearing, payment, farewell, and follow-up', null, 1),
  ('b315b506-bb86-42b0-94b2-82eb2ee57916', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '60270749-f737-456c-84f1-0f7e0fc63cb5', 'concept'::public.curated_course_node_type, 'Reservations, waitlists, table assignment, pacing, turns, sections, and kitchen-bar coordination', null, 2),
  ('b50eea3c-6140-41bc-b052-4aed3f39d85d', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '3f724acd-db34-4e7f-8b09-bc2b0b518002', 'subtopic'::public.curated_course_node_type, 'Service quality and inclusive hospitality', 'Students translate the service promise into observable behaviors while adapting respectfully to individual needs.', 1),
  ('19c55622-6805-4572-a14c-ad079f7537bf', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'b50eea3c-6140-41bc-b052-4aed3f39d85d', 'concept'::public.curated_course_node_type, 'Reliability, responsiveness, assurance, empathy, tangibles, personalization, and anticipatory service', null, 0),
  ('aee47fc1-6c14-43da-b58e-1d27b48c731d', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'b50eea3c-6140-41bc-b052-4aed3f39d85d', 'concept'::public.curated_course_node_type, 'Accessibility, dietary/allergen communication, cultural humility, gender-inclusive language, privacy, and trauma-aware interaction', null, 1),
  ('7252a4e5-fed8-4b3c-8992-019a9203cf2a', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'b50eea3c-6140-41bc-b052-4aed3f39d85d', 'concept'::public.curated_course_node_type, 'Suggestive selling versus pressure, product knowledge, plain language, nonverbal communication, and professional boundaries', null, 2),
  ('8b8b8758-226b-48df-af12-e2e5137c1ffc', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '3f724acd-db34-4e7f-8b09-bc2b0b518002', 'subtopic'::public.curated_course_node_type, 'Complaints and service recovery', 'Students learn to respond quickly, protect safety, restore trust, and convert incidents into operational learning.', 2),
  ('d6f7d646-67d7-4c1a-97b4-a4f1bf76fb18', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '8b8b8758-226b-48df-af12-e2e5137c1ffc', 'concept'::public.curated_course_node_type, 'Listen, acknowledge, clarify, apologize appropriately, resolve, document, follow up, and close the loop', null, 0),
  ('5df468ae-a522-49ff-898d-5703af7ef977', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '8b8b8758-226b-48df-af12-e2e5137c1ffc', 'concept'::public.curated_course_node_type, 'Empowerment limits, escalation, comps, refunds, remakes, safety allegations, discrimination, harassment, and security', null, 1),
  ('39654b2a-ab73-405f-8c6f-c68d183d71ff', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '8b8b8758-226b-48df-af12-e2e5137c1ffc', 'concept'::public.curated_course_node_type, 'Complaint coding, sentiment, repeat issues, recovery cost, root cause, and preventive change', null, 2),
  ('3a54252d-ca17-4c3f-8697-27d4ef44f627', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', null, 'topic'::public.curated_course_node_type, 'Catering, Banquets, and Off-Premise Operations', 'Catering and banquets combine sales promises with complex production, logistics, timing, room, staffing, and client coordination. Students learn to control the handoff from inquiry to event closeout.', 7),
  ('767f6bae-c00b-4c5c-aafb-69a8ac9e0f88', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '3a54252d-ca17-4c3f-8697-27d4ef44f627', 'subtopic'::public.curated_course_node_type, 'Sales, contracts, and event documentation', 'Students turn client needs into a precise, approved, and financially controlled scope.', 0),
  ('aa64bb8b-a26d-48e4-afe7-c17617843643', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '767f6bae-c00b-4c5c-aafb-69a8ac9e0f88', 'concept'::public.curated_course_node_type, 'Inquiry, qualification, site visit, proposal, tasting, contract, deposit, guarantees, cutoffs, cancellation, and force majeure', null, 0),
  ('afa87f63-6ec4-4007-a25d-bc1fbd23fa1d', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '767f6bae-c00b-4c5c-aafb-69a8ac9e0f88', 'concept'::public.curated_course_node_type, 'Banquet event order, function sheet, diagrams, menus, timelines, allergies, rentals, audiovisual, security, and contacts', null, 1),
  ('7de78053-ed09-415b-8ec0-3c8c02f572e3', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '767f6bae-c00b-4c5c-aafb-69a8ac9e0f88', 'concept'::public.curated_course_node_type, 'Change control, approvals, payment schedule, gratuities/service charges, taxes, attrition, and post-event settlement', null, 2),
  ('0813b82b-21ab-4bff-aeb6-41b8d7de99ea', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '3a54252d-ca17-4c3f-8697-27d4ef44f627', 'subtopic'::public.curated_course_node_type, 'Event production and service logistics', 'Students coordinate food, beverage, equipment, people, rooms, vendors, and timing across a temporary operating system.', 1),
  ('063a2e91-e079-4fe3-868c-2af93e7db76e', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '0813b82b-21ab-4bff-aeb6-41b8d7de99ea', 'concept'::public.curated_course_node_type, 'On-premise versus off-premise, transport, loading, holding, satellite kitchens, utilities, weather, permits, and emergency plans', null, 0),
  ('9cfee9df-3794-4eed-831f-4f073a530e53', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '0813b82b-21ab-4bff-aeb6-41b8d7de99ea', 'concept'::public.curated_course_node_type, 'Buffet, reception, plated, family, stations, breaks, bars, concessions, and high-volume service', null, 1),
  ('eff6ca85-69d5-4833-8783-11311c010fd9', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '0813b82b-21ab-4bff-aeb6-41b8d7de99ea', 'concept'::public.curated_course_node_type, 'Setup, room turn, staffing, briefing, replenishment, clearing, teardown, returns, and lost/damaged items', null, 2),
  ('0f3aafe4-ba7e-4c7a-84d0-a12990d1266c', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '3a54252d-ca17-4c3f-8697-27d4ef44f627', 'subtopic'::public.curated_course_node_type, 'Catering quality, profitability, and review', 'Students measure whether the event met guest, client, employee, safety, and financial expectations.', 2),
  ('5d49023b-d239-4414-9823-09aab23a549e', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '0f3aafe4-ba7e-4c7a-84d0-a12990d1266c', 'concept'::public.curated_course_node_type, 'Per-person and package pricing, minimums, labor/equipment/rental/delivery charges, contribution, and break-even', null, 0),
  ('539fc609-b241-45b1-8356-38b13ac50cff', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '0f3aafe4-ba7e-4c7a-84d0-a12990d1266c', 'concept'::public.curated_course_node_type, 'Guarantee versus actual, consumption, waste, overtime, substitutions, claims, and event variance', null, 1),
  ('00a6b444-b7b3-48ee-bc24-ec5eb7bb6924', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '0f3aafe4-ba7e-4c7a-84d0-a12990d1266c', 'concept'::public.curated_course_node_type, 'Client debrief, team after-action review, vendor evaluation, incident log, lessons, and repeat-business plan', null, 2),
  ('542ee2f3-8114-49a9-bbdc-917088aec5f1', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', null, 'topic'::public.curated_course_node_type, 'Facilities, Equipment, Layout, and Maintenance', 'Facilities determine capacity, workflow, safety, experience, and operating cost. Students learn to evaluate a space and equipment plan against the menu, service model, code, accessibility, utilities, maintenance, and life-cycle value.', 8),
  ('d1d49899-acab-4a6c-91e0-08203ddee5e6', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '542ee2f3-8114-49a9-bbdc-917088aec5f1', 'subtopic'::public.curated_course_node_type, 'Facility planning and flow', 'Students begin with the operating program and map all flows before judging the layout.', 0),
  ('eccda4a5-8b75-4e2e-8196-e1fd3df87415', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'd1d49899-acab-4a6c-91e0-08203ddee5e6', 'concept'::public.curated_course_node_type, 'Receiving, storage, prep, cooking, plating, service, warewashing, waste, employee, guest, and delivery-driver flows', null, 0),
  ('e634169c-e2af-40ce-af2a-104b88a49435', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'd1d49899-acab-4a6c-91e0-08203ddee5e6', 'concept'::public.curated_course_node_type, 'Adjacencies, separation of clean/dirty and raw/ready-to-eat, visibility, queueing, acoustics, lighting, security, and wayfinding', null, 1),
  ('7a74b5e9-5f39-41aa-9356-202a57f22a56', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'd1d49899-acab-4a6c-91e0-08203ddee5e6', 'concept'::public.curated_course_node_type, 'Seat count, table mix, bar capacity, toilets, accessibility, egress, loading, and back-of-house support', null, 2),
  ('d6fc8939-0b44-406c-9f3f-819abd087479', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '542ee2f3-8114-49a9-bbdc-917088aec5f1', 'subtopic'::public.curated_course_node_type, 'Equipment selection and capacity', 'Students select equipment for performance, throughput, quality, safety, flexibility, utilities, training, and total cost.', 1),
  ('dad7267a-0139-4158-a694-56a6282aee4f', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'd6fc8939-0b44-406c-9f3f-819abd087479', 'concept'::public.curated_course_node_type, 'Menu and process requirements, rated versus practical capacity, peak demand, redundancy, and bottlenecks', null, 0),
  ('42a31d84-acb8-4ae7-b780-7c90fbe276c4', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'd6fc8939-0b44-406c-9f3f-819abd087479', 'concept'::public.curated_course_node_type, 'Cooking, refrigeration, warewashing, beverage, ventilation, fire suppression, water, gas, electric, and controls', null, 1),
  ('69ddafa4-a553-4372-93df-f822f11f390f', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'd6fc8939-0b44-406c-9f3f-819abd087479', 'concept'::public.curated_course_node_type, 'Purchase, lease, used equipment, installation, certification, life-cycle cost, ergonomics, cleanability, and future flexibility', null, 2),
  ('ff844015-7e75-4d9d-97f1-9065faea12a0', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '542ee2f3-8114-49a9-bbdc-917088aec5f1', 'subtopic'::public.curated_course_node_type, 'Maintenance and asset management', 'Students create systems that prevent unsafe failures and expensive unplanned downtime.', 2),
  ('94e6cd56-7485-48e9-9090-5e6de4358c72', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'ff844015-7e75-4d9d-97f1-9065faea12a0', 'concept'::public.curated_course_node_type, 'Asset register, preventive and predictive maintenance, cleaning, inspection, calibration, and service records', null, 0),
  ('7b8f22ee-aa8f-4aea-af34-bdcbcde517ee', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'ff844015-7e75-4d9d-97f1-9065faea12a0', 'concept'::public.curated_course_node_type, 'Work orders, priority, downtime, spare parts, service contracts, warranties, and vendor performance', null, 1),
  ('a121e4a9-6488-4cb0-8a15-9813a37dd7d7', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'ff844015-7e75-4d9d-97f1-9065faea12a0', 'concept'::public.curated_course_node_type, 'Capital replacement, condition, useful life, energy/water performance, commissioning, and emergency contingencies', null, 2),
  ('c259a72d-56a1-4eb7-923d-3d297731d1a2', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', null, 'topic'::public.curated_course_node_type, 'Workforce Planning, Labor Scheduling, and Leadership', 'Food and beverage performance depends on skilled people working across variable demand and high-pressure service periods. Students learn to plan labor lawfully, lead inclusively, build competence, and retain talent.', 9);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('6fc77b30-f8b7-4b06-b122-ab8147125a45', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'c259a72d-56a1-4eb7-923d-3d297731d1a2', 'subtopic'::public.curated_course_node_type, 'Staffing models and labor forecasting', 'Students translate forecast demand, service standards, station workload, and skill needs into coverage.', 0),
  ('03a04971-3f03-4d33-81fe-8f5eaf3d91a0', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '6fc77b30-f8b7-4b06-b122-ab8147125a45', 'concept'::public.curated_course_node_type, 'Organization charts, roles, job descriptions, competencies, span of control, and cross-functional interfaces', null, 0),
  ('5625f6f4-adfd-4997-9b73-df3a34f14059', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '6fc77b30-f8b7-4b06-b122-ab8147125a45', 'concept'::public.curated_course_node_type, 'Covers, transactions, sales, labor hours, productivity, minimum staffing, skill mix, and relief factors', null, 1),
  ('d45d1be4-5c60-459e-9a02-6bc9a8fe0ea1', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '6fc77b30-f8b7-4b06-b122-ab8147125a45', 'concept'::public.curated_course_node_type, 'Fixed, variable, flexible, staggered, split, on-call, banquet, and cross-trained staffing approaches', null, 2),
  ('71be4508-4584-4787-9535-287df48a7aac', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'c259a72d-56a1-4eb7-923d-3d297731d1a2', 'subtopic'::public.curated_course_node_type, 'Scheduling, labor control, and compliance', 'Students build schedules that balance service, cost, fairness, availability, fatigue, and legal requirements.', 1),
  ('c9376302-cf4c-4ea1-954f-ca586e430401', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '71be4508-4584-4787-9535-287df48a7aac', 'concept'::public.curated_course_node_type, 'Availability, time-off, seniority/collective agreements, minors, breaks, overtime, rest periods, scheduling laws, and accommodations', null, 0),
  ('97d99532-37a1-4af5-af19-986eda4fcc3c', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '71be4508-4584-4787-9535-287df48a7aac', 'concept'::public.curated_course_node_type, 'Schedule construction, shift bids, swaps, call-outs, weather/events, agency labor, tip rules, timekeeping, and payroll controls', null, 1),
  ('22c934ee-e1fc-459b-ab05-484107ff26c7', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '71be4508-4584-4787-9535-287df48a7aac', 'concept'::public.curated_course_node_type, 'Labor cost percentage, sales per labor hour, covers per labor hour, schedule variance, overtime, and service/quality balancing measures', null, 2),
  ('5683dfa1-e4b2-4d94-a32f-5d2f0b0f92e8', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'c259a72d-56a1-4eb7-923d-3d297731d1a2', 'subtopic'::public.curated_course_node_type, 'Leadership, training, and performance', 'Students practice the management behaviors that create clarity, trust, accountability, development, and psychological safety.', 2),
  ('f8235424-52df-4713-8a5d-be5c98c22240', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '5683dfa1-e4b2-4d94-a32f-5d2f0b0f92e8', 'concept'::public.curated_course_node_type, 'Recruitment, structured selection, onboarding, culture, expectations, and early retention', null, 0),
  ('46fcdf60-71fb-4a91-a017-c27e8bdae955', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '5683dfa1-e4b2-4d94-a32f-5d2f0b0f92e8', 'concept'::public.curated_course_node_type, 'Pre-shifts, demonstrations, job aids, coaching, feedback, conflict, recognition, discipline, and documentation', null, 1),
  ('5f493420-1963-4b82-a540-072a9b4d5157', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '5683dfa1-e4b2-4d94-a32f-5d2f0b0f92e8', 'concept'::public.curated_course_node_type, 'Harassment prevention, bystander action, diversity and belonging, well-being, burnout, succession, and manager development', null, 2),
  ('ef9b083d-2559-459b-b353-e96bbe7b3fd6', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', null, 'topic'::public.curated_course_node_type, 'Financial Controls, Revenue, and Profitability', 'Managers need to understand how operational decisions appear in financial results. Students learn to control transactions, interpret performance, explain variance, and improve profit without compromising safety, value, or employees.', 10),
  ('4ff5afa7-5e76-4c93-94be-bf1ba23bf0ff', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'ef9b083d-2559-459b-b353-e96bbe7b3fd6', 'subtopic'::public.curated_course_node_type, 'Restaurant financial statements and metrics', 'Students read the operating statement and connect each line to controllable activities.', 0),
  ('4eb335f5-4e2e-4f73-97f3-1cf18426cece', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '4ff5afa7-5e76-4c93-94be-bf1ba23bf0ff', 'concept'::public.curated_course_node_type, 'Sales by channel/daypart/category, discounts, comps, taxes, service charges, tips, refunds, and net sales', null, 0),
  ('cda81d1d-2797-4f82-9d58-8449cbc2571d', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '4ff5afa7-5e76-4c93-94be-bf1ba23bf0ff', 'concept'::public.curated_course_node_type, 'Cost of sales, labor, prime cost, operating expenses, occupancy, fixed/variable/semivariable costs, EBITDA awareness, and cash flow', null, 1),
  ('b988ea85-590e-42bc-8699-f29dd957ea19', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '4ff5afa7-5e76-4c93-94be-bf1ba23bf0ff', 'concept'::public.curated_course_node_type, 'Common-size analysis, budget versus actual, prior period, benchmark, trend, and unit/department comparison', null, 2),
  ('e9c0b42d-7786-4d6e-a373-e25e5a066c67', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'ef9b083d-2559-459b-b353-e96bbe7b3fd6', 'subtopic'::public.curated_course_node_type, 'Cost and transaction controls', 'Students design a documented trail from purchase and time worked through sale, payment, deposit, and reporting.', 1),
  ('b541aa1b-7e30-4d1d-8c8f-621a5a8be397', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'e9c0b42d-7786-4d6e-a373-e25e5a066c67', 'concept'::public.curated_course_node_type, 'Purchasing authority, receiving separation, invoices, credits, inventory, recipe/portion controls, transfers, and waste', null, 0),
  ('88bde2d0-d5ad-474d-b34c-ef8b7a9f3a92', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'e9c0b42d-7786-4d6e-a373-e25e5a066c67', 'concept'::public.curated_course_node_type, 'POS permissions, modifiers, discounts, voids, refunds, comps, tips, gift cards, cash drawers, payment cards, chargebacks, and deposits', null, 1),
  ('ff6f0bb6-bb9e-4e12-b10a-9ad523f1f414', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'e9c0b42d-7786-4d6e-a373-e25e5a066c67', 'concept'::public.curated_course_node_type, 'Segregation of duties, exception reports, reconciliation, audit trail, fraud indicators, and corrective action', null, 2),
  ('c73101b4-668b-4de0-8cca-55a05b66a17e', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'ef9b083d-2559-459b-b353-e96bbe7b3fd6', 'subtopic'::public.curated_course_node_type, 'Revenue and profit improvement', 'Students choose improvements using contribution, capacity, demand, guest value, and risk—not indiscriminate cost cutting.', 2),
  ('b1fbfdd5-66b5-4d12-a001-0ef43bcf01a8', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'c73101b4-668b-4de0-8cca-55a05b66a17e', 'concept'::public.curated_course_node_type, 'Average check, covers, seats, turns, occupancy, RevPASH, mix, attachment, conversion, retention, and channel contribution', null, 0),
  ('fb93b171-7ed2-4d95-9510-0d2e3a92602e', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'c73101b4-668b-4de0-8cca-55a05b66a17e', 'concept'::public.curated_course_node_type, 'Forecasting, reservations, pacing, table mix, daypart development, offers, bundles, upselling, and capacity smoothing', null, 1),
  ('aa68a1a3-60a6-4516-bf52-1e86f447604b', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'c73101b4-668b-4de0-8cca-55a05b66a17e', 'concept'::public.curated_course_node_type, 'Break-even, CVP, sensitivity, scenario, marginal decision-making, price tests, and post-implementation measurement', null, 2),
  ('696d4f74-d724-41e0-abf4-88166c1bfbea', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', null, 'topic'::public.curated_course_node_type, 'Technology, Data Analytics, and Digital Operations', 'Technology connects ordering, production, labor, inventory, payments, loyalty, and management decisions. Students learn to select and govern systems that improve work and experience without creating avoidable privacy, cybersecurity, or accessibility risk.', 11),
  ('181a974f-0bd8-4194-9b84-e7032aa44751', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '696d4f74-d724-41e0-abf4-88166c1bfbea', 'subtopic'::public.curated_course_node_type, 'Restaurant technology ecosystem', 'Students map the operational purpose and interfaces of major systems.', 0),
  ('4f4cd2a8-cbe3-480a-8f6a-e156f5d2a7d3', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '181a974f-0bd8-4194-9b84-e7032aa44751', 'concept'::public.curated_course_node_type, 'POS, kitchen display, handhelds, reservations/waitlist, online ordering, delivery aggregators, inventory, procurement, recipes, scheduling, payroll, CRM, loyalty, and accounting', null, 0),
  ('40c14930-5d49-4e2d-9f2d-f290331101ef', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '181a974f-0bd8-4194-9b84-e7032aa44751', 'concept'::public.curated_course_node_type, 'Payments, gift cards, kiosks, QR menus, digital signage, sensors, robotics, AI-assisted tools, and integration middleware', null, 1),
  ('c3487eb3-5593-4286-b469-08ddb8df1bf9', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '181a974f-0bd8-4194-9b84-e7032aa44751', 'concept'::public.curated_course_node_type, 'Requirements, vendor selection, implementation, data migration, training, support, uptime, and total cost', null, 2),
  ('392236ee-391f-48c2-8912-0c3376aa2c3f', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '696d4f74-d724-41e0-abf4-88166c1bfbea', 'subtopic'::public.curated_course_node_type, 'Data and decision support', 'Students turn transactional data into defined measures and actionable questions.', 1),
  ('b44fbdb1-bd25-4299-88b7-65814a32f30f', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '392236ee-391f-48c2-8912-0c3376aa2c3f', 'concept'::public.curated_course_node_type, 'Data quality, item/master data, time stamps, channels, discounts, modifiers, employee/guest identifiers, and reconciliations', null, 0),
  ('7ca7814d-77ba-4b4e-85d5-06686c267e2a', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '392236ee-391f-48c2-8912-0c3376aa2c3f', 'concept'::public.curated_course_node_type, 'Dashboards, daypart/category analysis, menu mix, labor productivity, forecast error, waste, guest sentiment, and exception reporting', null, 1),
  ('b0a9eb59-81a8-470f-93b1-b433f90ecac7', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '392236ee-391f-48c2-8912-0c3376aa2c3f', 'concept'::public.curated_course_node_type, 'Operational definitions, denominators, segmentation, correlation versus causation, experiments, visualization, and data storytelling', null, 2),
  ('95b9d2df-703e-4d4a-b213-67a196aed86c', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '696d4f74-d724-41e0-abf4-88166c1bfbea', 'subtopic'::public.curated_course_node_type, 'Privacy, security, and continuity', 'Students recognize that connected operations introduce new obligations and failure modes.', 2),
  ('d85a874f-bbd0-4c37-b3bd-c47650ad6336', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '95b9d2df-703e-4d4a-b213-67a196aed86c', 'concept'::public.curated_course_node_type, 'Role-based access, strong authentication, least privilege, audit logs, device management, vendor access, phishing, and incident response', null, 0),
  ('87415596-fa49-468a-a706-10d3295d526d', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '95b9d2df-703e-4d4a-b213-67a196aed86c', 'concept'::public.curated_course_node_type, 'Payment-card security awareness, guest and employee privacy, camera/biometric concerns, retention, consent, and responsible AI', null, 1),
  ('6a3cc192-eef7-4c94-9ea0-8345cd9145ce', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '95b9d2df-703e-4d4a-b213-67a196aed86c', 'concept'::public.curated_course_node_type, 'Backups, offline modes, outage procedures, manual checks, cyber insurance, recovery priorities, and post-incident review', null, 2),
  ('35860499-bb25-4b7b-badf-53bb8d0b9aa6', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', null, 'topic'::public.curated_course_node_type, 'Marketing, CRM, Reputation, and Community', 'Food and beverage marketing is inseparable from experience delivery. Students learn to attract appropriate demand, communicate truthfully, build relationships, and protect reputation across owned, paid, earned, and partner channels.', 12),
  ('947c8c18-4035-4c77-8c08-aed4ed79b912', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '35860499-bb25-4b7b-badf-53bb8d0b9aa6', 'subtopic'::public.curated_course_node_type, 'Positioning and demand generation', 'Students connect concept and guest insight to a focused market promise and channel plan.', 0);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('2afeca4e-393e-4c53-a61f-c32b4c1c936b', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '947c8c18-4035-4c77-8c08-aed4ed79b912', 'concept'::public.curated_course_node_type, 'Segmentation, target, positioning, brand identity, value proposition, tone, and content pillars', null, 0),
  ('5e5adeac-b76b-4e0d-b8b5-261783a88fe1', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '947c8c18-4035-4c77-8c08-aed4ed79b912', 'concept'::public.curated_course_node_type, 'Website, local search, social, email, partnerships, public relations, events, hotel cross-selling, and neighborhood outreach', null, 1),
  ('4f420d0d-2ceb-4f73-b0d6-5f3201d3b73c', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '947c8c18-4035-4c77-8c08-aed4ed79b912', 'concept'::public.curated_course_node_type, 'Campaign objective, audience, offer, creative, calendar, budget, attribution, conversion, and incrementality', null, 2),
  ('d2a9b724-c13d-40c2-9856-0200d119db7e', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '35860499-bb25-4b7b-badf-53bb8d0b9aa6', 'subtopic'::public.curated_course_node_type, 'CRM, loyalty, and guest lifetime value', 'Students use relationship data to improve relevance and retention without creating surveillance or unfair exclusion.', 1),
  ('1287af84-ef90-4dc9-b909-ba69e82d59e7', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'd2a9b724-c13d-40c2-9856-0200d119db7e', 'concept'::public.curated_course_node_type, 'First-party data, consent, preference centers, profiles, visit frequency, spend, occasion, and channel', null, 0),
  ('a7d0383a-71d4-4725-813e-1db4b9f77a4a', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'd2a9b724-c13d-40c2-9856-0200d119db7e', 'concept'::public.curated_course_node_type, 'Loyalty design, recognition, tiers, rewards, breakage, personalization, win-back, and service recovery', null, 1),
  ('759bb1ee-adec-41e6-bcc9-67c2c28666d9', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'd2a9b724-c13d-40c2-9856-0200d119db7e', 'concept'::public.curated_course_node_type, 'Acquisition cost, retention, repeat rate, cohort behavior, lifetime value, privacy, accessibility, and bias', null, 2),
  ('9fef3fa1-236d-4c38-a01f-66e15bb6dfe1', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '35860499-bb25-4b7b-badf-53bb8d0b9aa6', 'subtopic'::public.curated_course_node_type, 'Reputation and community relations', 'Students prepare to monitor and respond to reviews, crises, misinformation, and community concerns with evidence and empathy.', 2),
  ('5f28d759-08e4-492e-b91f-a229a2609ca1', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '9fef3fa1-236d-4c38-a01f-66e15bb6dfe1', 'concept'::public.curated_course_node_type, 'Review platforms, social listening, response standards, escalation, fake reviews, and learning from themes', null, 0),
  ('a6409613-c9fb-4823-83d5-8eea0fe9a5ca', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '9fef3fa1-236d-4c38-a01f-66e15bb6dfe1', 'concept'::public.curated_course_node_type, 'Food-safety, discrimination, employee, alcohol, security, environmental, and influencer crises', null, 1),
  ('c7a489d4-2e78-4867-8eaa-e834d16273d3', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '9fef3fa1-236d-4c38-a01f-66e15bb6dfe1', 'concept'::public.curated_course_node_type, 'Media holding statements, spokesperson, fact verification, stakeholder updates, corrective action, and community partnership', null, 2),
  ('351864cb-42ef-4e55-83c9-3826ac510f60', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', null, 'topic'::public.curated_course_node_type, 'Sustainability, Ethics, Inclusion, and Resilience', 'Responsible management considers environmental limits, employee and supplier welfare, guest access, community impact, and the ability to continue essential operations during disruption. Students learn to evaluate tradeoffs instead of relying on vague claims.', 13),
  ('26eda089-c1fe-4704-b63a-e0c3851b596d', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '351864cb-42ef-4e55-83c9-3826ac510f60', 'subtopic'::public.curated_course_node_type, 'Sustainable food, beverage, and materials', 'Students evaluate choices across sourcing, menus, utilities, packaging, and end-of-life systems.', 0),
  ('936d1d64-723b-4811-bbc5-1c5e4104378e', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '26eda089-c1fe-4704-b63a-e0c3851b596d', 'concept'::public.curated_course_node_type, 'Plant-forward design, seasonal/local sourcing, sustainable seafood, animal welfare, certified products, and beverage sourcing', null, 0),
  ('0af6c25f-a7d3-44e8-b398-a5c40f7cdfc5', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '26eda089-c1fe-4704-b63a-e0c3851b596d', 'concept'::public.curated_course_node_type, 'Energy, water, refrigerants, ventilation, transport, reusable serviceware, packaging, recycling, composting, and credible claims', null, 1),
  ('87213e87-0d9d-4c74-8ab5-e2b216a48df5', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '26eda089-c1fe-4704-b63a-e0c3851b596d', 'concept'::public.curated_course_node_type, 'Life-cycle thinking, functional unit, cost, guest acceptance, supplier evidence, greenwashing, and rebound effects', null, 2),
  ('3b76b089-ebb7-448a-ae91-75d4371ff51a', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '351864cb-42ef-4e55-83c9-3826ac510f60', 'subtopic'::public.curated_course_node_type, 'Waste prevention and ethical operations', 'Students prioritize prevention and examine who benefits or bears risk in operating decisions.', 1),
  ('6542839e-8bf3-48f4-bf09-58241067d41b', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '3b76b089-ebb7-448a-ae91-75d4371ff51a', 'concept'::public.curated_course_node_type, 'Forecasting, batch/portion adjustment, cross-utilization, donation, by-product use, composting, and waste audits', null, 0),
  ('b8ad525d-5bfe-4b02-b709-3643999c2889', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '3b76b089-ebb7-448a-ae91-75d4371ff51a', 'concept'::public.curated_course_node_type, 'Fair scheduling, wages/tips, safe work, harassment prevention, supplier labor, conflicts of interest, bribery, and truthful selling', null, 1),
  ('10b98ff0-7965-449d-9d08-ea55e17b5e6d', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '3b76b089-ebb7-448a-ae91-75d4371ff51a', 'concept'::public.curated_course_node_type, 'Food access, cultural respect, accessibility, dietary inclusion, community impact, and responsible alcohol practices', null, 2),
  ('428fa53e-1fb7-4098-a3be-16993d5dfdd8', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '351864cb-42ef-4e55-83c9-3826ac510f60', 'subtopic'::public.curated_course_node_type, 'Emergency and business continuity', 'Students plan how to protect people, product, cash, data, and reputation during disruption.', 2),
  ('9b5fdbb7-b4f8-436b-96e9-e1f661694323', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '428fa53e-1fb7-4098-a3be-16993d5dfdd8', 'concept'::public.curated_course_node_type, 'Fire, severe weather, power/water failure, refrigeration loss, boil-water notice, outbreak, recall, violence, cyberattack, and supply failure', null, 0),
  ('ddd214c3-aab4-41a6-bcd2-6c999f5c60d6', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '428fa53e-1fb7-4098-a3be-16993d5dfdd8', 'concept'::public.curated_course_node_type, 'Emergency authority, contacts, evacuation/shelter, alternate menu/suppliers, manual operations, communications, insurance, and reopening criteria', null, 1),
  ('7979a74a-ca11-494c-81c7-40477116cea3', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '428fa53e-1fb7-4098-a3be-16993d5dfdd8', 'concept'::public.curated_course_node_type, 'Drills, incident command awareness, decision logs, after-action review, corrective actions, and resilience investment', null, 2),
  ('03c7b0df-f227-463c-8643-d4a2510b9ea4', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', null, 'topic'::public.curated_course_node_type, 'Restaurant Operations Project and Professional Integration', 'The capstone requires students to integrate the entire course into a decision-ready concept or improvement plan. The goal is not a glossy idea but an operationally executable, financially defensible, safe, inclusive, and measurable proposal.', 14),
  ('ce322c71-8154-43d1-968f-7ce367dab5c3', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '03c7b0df-f227-463c-8643-d4a2510b9ea4', 'subtopic'::public.curated_course_node_type, 'Project framing and evidence', 'Students define a bounded opportunity, affected stakeholders, baseline, criteria, and evidence plan.', 0),
  ('1691d364-fb71-4306-bb07-5c0bfc4388f5', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'ce322c71-8154-43d1-968f-7ce367dab5c3', 'concept'::public.curated_course_node_type, 'Concept launch, menu revision, bar program, catering service, technology change, capacity redesign, cost problem, or guest-experience improvement', null, 0),
  ('a48f6c7c-fb02-4fb6-8b59-e637a99b3d64', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'ce322c71-8154-43d1-968f-7ce367dab5c3', 'concept'::public.curated_course_node_type, 'Charter, scope, sponsor, stakeholders, guest need, assumptions, constraints, risks, ethics, and success measures', null, 1),
  ('bed851b8-b81b-4de3-b2a3-719357afb67a', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'ce322c71-8154-43d1-968f-7ce367dab5c3', 'concept'::public.curated_course_node_type, 'Market research, observation, interviews, operational data, standards, literature, competitors, and benchmarking', null, 2),
  ('2934fc5c-5eb2-42b7-90da-b52fe7cc51bd', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '03c7b0df-f227-463c-8643-d4a2510b9ea4', 'subtopic'::public.curated_course_node_type, 'Integrated operating and financial plan', 'Students show exactly how the proposal would function from purchase through guest experience and control.', 1),
  ('ff2940be-5696-4093-8f16-b81ee3866d77', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '2934fc5c-5eb2-42b7-90da-b52fe7cc51bd', 'concept'::public.curated_course_node_type, 'Concept/menu, demand forecast, purchasing, production, food safety, beverage, service, catering/off-premise, and quality plan', null, 0),
  ('0af7b6f5-1415-4383-b6aa-30e9d33075d1', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '2934fc5c-5eb2-42b7-90da-b52fe7cc51bd', 'concept'::public.curated_course_node_type, 'Facility/equipment, staffing/schedule/training, technology, marketing, accessibility, sustainability, and emergency continuity', null, 1),
  ('c5656131-8440-4e1d-9c5b-3039ef3a42ce', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '2934fc5c-5eb2-42b7-90da-b52fe7cc51bd', 'concept'::public.curated_course_node_type, 'Startup and operating budget, pricing, sales forecast, prime cost, break-even, cash needs, sensitivity, and implementation timeline', null, 2),
  ('b452a09e-e217-4399-b9c3-81eb0c62d57d', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', '03c7b0df-f227-463c-8643-d4a2510b9ea4', 'subtopic'::public.curated_course_node_type, 'Pilot, evaluation, and executive defense', 'Students state what will be tested, how success will be measured, and what evidence would change the recommendation.', 2),
  ('79c1e598-91fe-48d5-af4a-a548f075ec16', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'b452a09e-e217-4399-b9c3-81eb0c62d57d', 'concept'::public.curated_course_node_type, 'Prototype or pilot, acceptance criteria, process/outcome/balancing measures, dashboard, and feedback plan', null, 0),
  ('769555c0-4e1b-4844-921d-bc1f142eb569', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'b452a09e-e217-4399-b9c3-81eb0c62d57d', 'concept'::public.curated_course_node_type, 'Risk register, contingency, PDSA cycle, stop/continue/scale decision rules, and limitations', null, 1),
  ('8f7a646f-a016-4167-993c-044c83a51b16', 'b7c8d9e0-1f2a-4b12-9c41-5d6e7f8a9b02', 'b452a09e-e217-4399-b9c3-81eb0c62d57d', 'concept'::public.curated_course_node_type, 'Executive brief, technical appendix, visual presentation, questions, peer review, reflection, and handoff', null, 2);
